-- Read-only validation after the import.
select data_origin,count(*)::integer from public.fd_directory_businesses group by data_origin;
select count(*)::integer as google_rating_rows from public.fd_directory_businesses where lower(coalesce(rating_source,'')||' '||coalesce(rating_origin,'')) ~ '(google|places[ _-]?api)';
select count(*)::integer as raw_google_source_rows from public.fd_directory_source_records where lower(provider) ~ '(google|places[ _-]?api)';
select count(*)::integer as pilot_providers,count(google_place_id)::integer as place_ids,count(review_rating)::integer as stored_ratings from public.fd_directory_businesses where seed_key in ('alfonsos-mobile-sarasota','and-a-leash-tampa','bark-and-mane-sarasota','bark-and-mane-tampa-bay','chasing-sunshine-mobile-sarasota','cutie-pawtootie-mobile','dappertails-north-tampa','dog-world-blaikie','doggo-den-n-tamiami','doggyday-inn-tampa','dogperfect-landings','dogperfect-university-park','downtown-doggie-st-pete','fur-seasons-superior','groomingdales-tampa','happy-paws-bee-ridge','lavish-dog-spa-central-sarasota','love-my-dog-grooming-st-pete','paws-n-rec-sarasota','paws-n-rec-pearl-tampa','paws-n-rec-st-pete','pawsh-southgate','petco-sarasota-2710','petco-sarasota-south-1590','petco-sarasota-utc-1536','puppy-manor-tampa','puptown-mobile-tampa-bay','rover-done-over-tampa','sarasota-grooming-company-reynolds','seaside-paw-spa-washington','spot-srq-dolphin','sarasota-dog-salon-palmer','sudsy-pup-fruitville','two-mutts-st-pete','urbanwagz-tampa','well-groomed-pets-fruitville','wet-noses-main-street','woof-gang-cattlemen','woof-gang-waterside','woofies-mobile-st-pete','wuts-up-pup-washington');
